  select $drill${"key":"structured_logs","fact":"app_log_hourly","mode":"definer","grain":"one row per hour for each level, feature, route, logger, exception kind, host role, classified and person","label":"Structured logs","lanes":["platform","mine"],"paths":[{"key":"when","label":"When","levels":["created_at:day","created_at:hour"]}],"default":{"by":["level"],"show":["count","people"],"sort":{"key":"count","direction":"desc"}},"records":{"fact":"app_log_lines","labels":{"id":"Log line","user_id":"Person","exc_type":"Exception kind","host_role":"Host role","created_at":"When","request_id":"Request","logger_name":"Logger"},"columns":["created_at","level","feature","route","logger_name","message","exc_type","request_id","user_id","host_role","classified","id"]},"measures":[{"of":"lines","op":"sum","key":"count","unit":"count","label":"Log lines","additive":true},{"of":"requests","op":"sum","key":"requests","unit":"count","label":"Requests","additive":true,"description":"Per hour and group, not exact: a request spanning hours or groups counts in each"},{"of":"user_id","op":"count_distinct","key":"people","unit":"count","label":"People","additive":false}],"dimensions":[{"key":"level","from":"level","kind":"choice","label":"Level","level":{"show":["count","people"],"breakouts":["feature","route","logger_name","exc_type","created_at:hour"]},"choices":[{"label":"Debug","value":"DEBUG"},{"label":"Info","value":"INFO"},{"label":"Warning","value":"WARNING"},{"label":"Error","value":"ERROR"},{"label":"Critical","value":"CRITICAL"}],"cardinality":"low"},{"key":"feature","from":"feature","kind":"text","label":"Feature","level":{"show":["count","people"],"breakouts":["level","route","exc_type","logger_name","created_at:hour"]},"cardinality":"medium","empty_label":"No feature stamped"},{"key":"route","from":"route","kind":"text","label":"Route","level":{"show":["count","people"],"breakouts":["level","feature","exc_type","created_at:hour"]},"cardinality":"medium","empty_label":"No route"},{"key":"logger_name","from":"logger_name","kind":"text","label":"Logger","level":{"show":["count","people"],"breakouts":["level","feature","route","created_at:hour"]},"cardinality":"medium"},{"key":"exc_type","from":"exc_type","kind":"text","label":"Exception kind","level":{"show":["count","people"],"breakouts":["feature","route","level","created_at:hour"]},"cardinality":"medium","empty_label":"No exception"},{"key":"host_role","from":"host_role","kind":"text","label":"Host role","cardinality":"low","empty_label":"Not stamped"},{"key":"classified","from":"classified","kind":"boolean","label":"Classified"},{"key":"created_at","from":"created_at","kind":"time","label":"When","grains":["year","quarter","month","week","day","hour"]}],"lane_rules":{"mine":{"column":"user_id"},"platform":{"rule":"super_admin"}},"stale_after_knob":"drill.app_log.stale_after_minutes"}$drill$::jsonb;
